// One icon per measure, so a list can be read at a glance.
const ICON_FOR = { pulse: 'heart-pulse', bp: 'activity', glucose: 'droplet', temp: 'thermometer', spo2: 'droplets', sleep: 'moon', resp: 'wind', fluid: 'glass-water', bodyMass: 'scale', eyePressure: 'eye', hearing: 'ear', radiation: 'radiation', vo2max: 'heart', strength: 'dumbbell', bone: 'bone', camera: 'camera', mood: 'smile', attitude: 'battery', sleepQuality: 'bed', cognition: 'brain', reaction: 'zap', cycle: 'calendar-heart', xray: 'scan-line', ecg: 'chart-line', ultrasound: 'waves', exercise: 'flame', visionCheck: 'eye', octChange: 'eye', octScan: 'scan-line', symptoms: 'stethoscope', medicines: 'pill', co2: 'cloud-fog', cabinTemp: 'thermometer', cabinO2: 'orbit', cabinPressure: 'gauge', noise: 'volume-2', blood: 'test-tube' };
// The keys: screen, name, icon, and a short name for phones (index.html .key-short); the full name stays the key's
// accessible name. The medical record is the fifth key (src/medrecord.js, src/record-view.js).
const NAV = [['home', 'Today', 'house'], ['measures', 'All measures', 'list', 'Measures'], ['record', 'Medical record', 'user', 'Record'], ['alerts', 'Messages', 'bell'], ['setup', 'Settings', 'settings']];

const DAY = 24 * 60 * 60 * 1000;
const REAL = realPeople(INSPIRATION4.subjects);
const PEOPLE = [...CREW, SHIP, ...REAL];
const personById = Object.fromEntries(PEOPLE.map((p) => [p.id, p]));
const cellBy = Object.fromEntries(CELLS.map((c) => [c.indicator, c]));
const sourceFor = (indicator) => SOURCES.find((s) => s.indicator === indicator);

// ---------- small helpers ----------
const byId = (id) => document.getElementById(id);
function h(tag, props = {}, ...children) {
  const node = document.createElement(tag);
  for (const [k, v] of Object.entries(props || {})) {
    if (v === undefined || v === null || v === false) continue;
    if (k === 'class') node.className = v;
    else if (k === 'text') node.textContent = v;
    else if (k === 'dataset') Object.assign(node.dataset, v);
    else if (k.startsWith('on') && typeof v === 'function') node.addEventListener(k.slice(2), v);
    else node.setAttribute(k, v === true ? '' : String(v));
  }
  for (const c of children.flat()) {
    if (c === null || c === undefined || c === false) continue;
    node.append(c instanceof Node ? c : document.createTextNode(String(c)));
  }
  return node;
}
// replaceChildren would print null as text; fill() leaves out empty parts.
const fill = (host, ...kids) => host.replaceChildren(...kids.flat().filter((k) => k !== null && k !== undefined && k !== false));
const two = (n) => String(n).padStart(2, '0');
const fmtVal = (v) => (Number.isFinite(Number(v)) ? String(Math.round(Number(v) * 10) / 10) : String(v));
const fmtDT = (t) => fmtGMT(t);
// GMT day of the year, as on the ISS: "GMT 318/18:00".
const doy = (d) => Math.floor((Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()) - Date.UTC(d.getUTCFullYear(), 0, 0)) / DAY);
const gmtDOY = (t) => { const d = new Date(t); return `${doy(d)}/${two(d.getUTCHours())}:${two(d.getUTCMinutes())}`; };
const cap = (s) => (s ? s.charAt(0).toUpperCase() + s.slice(1) : s);
const ageText = (t, now) => { const hrs = (msOf(now) - msOf(t)) / 3.6e6; return hrs >= 48 ? `${Math.floor(hrs / 24)} days` : `${Math.max(1, Math.round(hrs))} h`; };
const lower = (s) => s.charAt(0).toLowerCase() + s.slice(1);
const msOf = (t) => (t instanceof Date ? t.getTime() : new Date(t).getTime());
const LV_CLASS = ['lv0', 'lv1', 'lv2', 'lv3'];

// One short notice at a time: a new one replaces the old, and a longer one stays longer. The box is always on the
// page (a live region, index.html #toast), and only its words change, so a screen reader hears every notice.
let toastTimer = 0;
let toastSet = 0;
function toast(text) {
  const box = byId('toast');
  if (!box || !text) return;
  clearTimeout(toastTimer);
  clearTimeout(toastSet);
  box.classList.remove('on');
  box.textContent = '';
  // Emptied first and filled a moment later, so the same words twice are announced twice.
  toastSet = setTimeout(() => {
    box.textContent = String(text);
    box.classList.add('on');
    toastTimer = setTimeout(() => { box.classList.remove('on'); box.textContent = ''; }, Math.max(3600, 70 * String(text).length));
  }, 40);
}

// Redrawing part of the screen must not drop the keyboard. The control that had the focus gets it back after the
// redraw, found by its data-fk key or its id, so the next Tab goes on from the same place (WCAG 2.4.3).
const selectorOf = (el) => (!el || el === document.body || !el.dataset ? null : el.dataset.fk ? `[data-fk="${CSS.escape(el.dataset.fk)}"]` : el.id ? `#${CSS.escape(el.id)}` : null);
// The same control after a redraw: the element itself while it is on the page, otherwise the one with its key.
function sameControl(el, sel) {
  if (el && el.isConnected && el.getClientRects().length) return el;
  return sel ? [...document.querySelectorAll(sel)].find((x) => x.getClientRects().length) || null : null;
}
function keepFocus(fn) {
  const a = document.activeElement;
  const sel = selectorOf(a);
  const out = fn();
  if (sel && (!a.isConnected || !document.activeElement || document.activeElement === document.body)) {
    const next = sameControl(null, sel);
    if (next) next.focus({ preventScroll: true });
  }
  return out;
}
// The notice box stays on the page (it is the live region); signing out only empties it, so the next person never
// reads the last person's notice.
function dropToast() {
  clearTimeout(toastTimer);
  clearTimeout(toastSet);
  const box = byId('toast');
  if (box) { box.classList.remove('on'); box.textContent = ''; }
}

// Per-device conveniences only (the switches of the situation, seen alerts). "Sound off" is not kept: it never
// passes to the next person, and it starts on again at every sign-in (NASA-STD-3001 Vol 2, 10114).
const KEY = 'jff-crew-ui-v1';
function loadPrefs() {
  try { return JSON.parse(localStorage.getItem(KEY) || '{}'); } catch { return {}; }
}
function savePrefs() {
  try { localStorage.setItem(KEY, JSON.stringify({ ship: ui.ship, seen: [...ui.seen].slice(-2000), example: ui.example, profile: ui.profile, mission: ui.mission })); } catch { /* storage blocked: the page still works */ }
}

// ---------- state ----------
const prefs = loadPrefs();
const ui = {
  person: null,
  screen: 'home',
  detail: null, // indicator, or 'blood:<analyte code>'
  period: 'flight',
  from: '',
  to: '',
  ship: { aiWorks: true, doctorOnBoard: false, linkToEarth: true, ...(prefs.ship || {}) },
  muted: false,
  example: prefs.example !== false,
  seen: new Set(prefs.seen || []),
  checkin: { mood: null, attitude: null, sleepQuality: null, weighing: [] },
  checkinOpen: false,
  find: '',
  backTo: 'measures',
  stepsDone: {},
  openGroups: new Set(),
  profile: prefs.profile || 'iss',
  // The crew's own mission, set in Settings while the example flight is off; kept on this device (src/mission.js).
  mission: readMission(prefs.mission),
  conn: { on: { isslive: false, spaceweather: false }, connected: {}, busy: {}, live: {} },
  exercising: false,
  exerciseUntil: 0,
  drill: null, // the drill in progress (src/drill.js): never kept, off at every sign-in
};
let store = null;
let stored = [];
let machine = null;
let drillMachine = null; // while a drill runs: the record plus that drill's readings, used only for the drill's alarms
let camStop = null;

// The time the screen lives in: with the example flight on, the example's "today" or later saved readings.
function nowTime() {
  // The steps of the alert log are not readings: looking at an alert never moves the screen's time (src/alert-log.js).
  const latest = Math.max(0, ...stored.filter((e) => e.kind !== 'alert').map((e) => msOf(e.time)).filter(Number.isFinite));
  return ui.example ? new Date(Math.max(msOf(MISSION.today), latest)) : new Date();
}

// The mission the screen lives in: the example flight while its switch is on, otherwise the crew's own mission
// from Settings (src/mission.js). With neither, no example date drives a chart or a forecast (review finding PO-5):
// the mission has no launch and no landing, no flight day is shown, and Today and the measure pages say what is missing.
const ownMission = () => (!ui.example && ui.mission ? missionTimes(ui.mission, nowTime()) : null);
const mission = () => ownMission() || (ui.example ? MISSION : { name: null, launch: null, landing: null, today: nowTime().toISOString(), none: true });
// The mission's critical tasks: the made-up ones of the example flight, or the crew's own (src/readiness.js).
const missionTasks = () => (ui.example ? exampleTasks(MISSION.launch) : ((ownMission() || {}).tasks || []));
// The day count of the status line: FD n in flight, L-n before launch, R+n after landing, or null without a mission.
function flightDayNow(now = nowTime()) {
  if (ui.example) { const n = Math.floor((msOf(now) - msOf(MISSION.launch)) / DAY) + 1; return { kind: 'flight', n, short: `FD ${n}`, words: `Flight day ${n}` }; }
  return ui.mission ? flightDay(ui.mission, now) : null;
}

function replay(events) {
  // The mission tells the machine which readings are pre-flight (hearing is judged against the pre-flight test).
  const m = createMachine({ cells: CELLS, crew: PEOPLE, state: ui.ship, mission: ui.example || ui.mission ? mission() : null });
  for (const ev of events) {
    if (ev.state) m.setState(ev.state);
    if (ev.kind === 'reading') m.receive({ ...ev.reading, person: ev.person, time: ev.time, example: Boolean(ev.example) });
    else m.review(ev.person, ev.time);
  }
  m.setState(ui.ship);
  return m;
}
// The machine the screen judges the person by never sees a drill's events (src/drill.js): they never count in the
// levels, the measures, the medical record or the summaries for the doctor. While a drill runs, a second machine adds
// that drill's readings, for the drill's own alarms only (alertsFor, shareCrewAlarm).
function rebuild() {
  const flight = ui.example ? exampleFlight(CREW) : [];
  // Elly's made-up cycle days (flow and symptoms) come on top of the example flight's start and end marks.
  const all = [...flight, ...exampleCycleDays(flight), ...stored].filter((e) => e.kind === 'reading' || e.kind === 'review').sort((a, b) => msOf(a.time) - msOf(b.time));
  machine = replay(all.filter((e) => !isDrill(e)));
  drillMachine = ui.drill ? replay(all.filter((e) => !isDrill(e) || e.drill === ui.drill.id)) : null;
}
// Runs fn with the drill's machine in place of the record's (both are plain objects; fn runs at once).
function withMachine(m, fn) {
  const record = machine;
  machine = m;
  try { return fn(); } finally { machine = record; }
}

// ---------- saving ----------
// Our own station server runs on this computer (http, localhost or 127.0.0.1); a static copy on the web has none.
// The same test as src/store.js.
const ownServer = () => location.protocol === 'http:' || location.hostname === 'localhost' || location.hostname === '127.0.0.1';
const apiUrl = (path) => new URL(path, location.href).href;
// The station server did not answer: what the person enters waits in this browser and goes when it answers (QA-08).
let serverDown = false;

// Events the station server has not taken yet. They stay on the screen, are kept in this browser, and are sent as
// soon as the server answers again. Like the browser store of a static copy, the list holds whoever entered them
// on this computer, so the record of a person who signed out meanwhile still reaches the server.
const WAIT_KEY = 'jff-crew-waiting-v1';
let waiting = (() => {
  try { const x = JSON.parse(localStorage.getItem(WAIT_KEY) || '[]'); return Array.isArray(x) ? x.filter((e) => e && e.kind && e.person && e.time) : []; } catch { return []; }
})();
let waitingKept = true; // false when this browser blocks storage: then the list lives only until the page closes
function saveWaiting() { try { localStorage.setItem(WAIT_KEY, JSON.stringify(waiting)); waitingKept = true; } catch { waitingKept = false; } }
const isWaiting = (e) => { const k = eventKey(e); return waiting.some((w) => eventKey(w) === k); };
function holdForServer(e) { if (!isWaiting(e)) { waiting.push(e); saveWaiting(); } schedulePoll(ALARM_RULES.retrySeconds); }
function dropWaiting(e) { const k = eventKey(e); waiting = waiting.filter((w) => eventKey(w) !== k); saveWaiting(); }

// What became of each message and crew line, by eventKey: from the server's answer, or the outbox at sign-in.
const savedAs = new Map();
// Messages to a doctor that were not saved: "Sent messages" lists them as "Not sent", with "Send again" (QA-06).
let unsent = [];

function forget(event) {
  stored = stored.filter((e) => e !== event);
  if (store && Array.isArray(store.events)) { const i = store.events.indexOf(event); if (i >= 0) store.events.splice(i, 1); }
}
function note(event, res, kind = store ? store.kind : 'memory') {
  const k = eventKey(event);
  if (event.kind === 'report') {
    savedAs.set(k, messageStatus(res, { to: event.report.to, storeKind: kind }));
    if (res.ok) unsent = unsent.filter((u) => !(u.event.report.to === event.report.to && u.event.report.text === event.report.text));
  }
  if (event.kind === 'alarm') savedAs.set(k, lineStatus(res, { storeKind: kind }));
  return res;
}
function failed(event, why, quiet) {
  if (event.kind === 'report') unsent = [...unsent.filter((u) => u.event !== event), { event, why }];
  if (event.kind === 'report' || event.kind === 'alarm') savedAs.set(eventKey(event), 'unsent');
  if (!quiet) toast(`Not saved: ${shortReason(why)}. Try again.`);
  return { ok: false, answer: null, why };
}
// The status of a saved message or crew line, for the words on the screen.
function statusOf(event) {
  if (!event) return null;
  if (isWaiting(event)) return 'waiting';
  const k = eventKey(event);
  if (savedAs.has(k)) return savedAs.get(k);
  const server = store && store.kind === 'server';
  if (event.kind === 'alarm') return server ? 'shared' : 'local';
  return server ? 'server' : 'local';
}

// Every event goes through here, and the answer says what really happened: { ok, answer } when saved; { ok, waiting }
// when it is kept in this browser until the station server answers; { ok: false, why } when it was not saved. An
// event that was not saved leaves the screen again, so the screen never shows more than the record holds (QA-06,
// QA-07). retry: a passing refusal of the station computer (a 5xx answer other than "no outbox key") is tried again
// too, for the parts of a call for help (QA-01).
async function keep(event, { quiet = false, retry = false, mark = true } = {}) {
  // While a drill runs, every new event carries its mark; a step of the alert log carries its alert's own, and a crew
  // line and its message the one shareCrewAlarm chose (mark: false), so a real alarm is never marked (src/drill.js).
  const drillMark = !mark || event.kind === 'alert' || event.drill ? null : markFor(ui.drill, event.time);
  if (drillMark) event.drill = drillMark;
  stored.push(event);
  if (serverDown && ownServer()) { holdForServer(event); return note(event, { ok: true, waiting: true, answer: null }); }
  if (!store) { forget(event); return failed(event, 'nothing is open to save into', quiet); }
  try {
    const answer = await store.append(event);
    return note(event, { ok: true, answer });
  } catch (err) {
    const why = String((err && err.message) || err);
    const answered = /^not saved: \d{3}/.test(why);
    if (store.kind === 'server' && (!answered || (retry && /^not saved: 5\d\d/.test(why) && !/^not saved: 503/.test(why)))) {
      if (!answered) { serverDown = true; schedulePoll(ALARM_RULES.retrySeconds); }
      holdForServer(event);
      return note(event, { ok: true, waiting: true, answer: null, why });
    }
    forget(event);
    return failed(event, why, quiet);
  }
}

// Sends what waits in this browser, oldest first. A refusal for good (4xx, or 503 "no outbox key") leaves the list
// and is reported; a passing one (5xx) stays for the next try; no answer at all stops until the next look.
let flushing = false;
async function flushWaiting() {
  const out = { sent: 0, refused: 0, reached: false, events: [] };
  if (flushing || !waiting.length || !ownServer()) return out;
  flushing = true;
  try {
    for (const e of [...waiting]) {
      let res;
      try {
        res = await fetch(apiUrl('./api/events'), { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, body: JSON.stringify(e) });
      } catch { break; }
      out.reached = true;
      if (res.ok) {
        let answer = null;
        if (res.status === 201) { try { answer = await res.json(); } catch { /* no answer body */ } }
        dropWaiting(e);
        note(e, { ok: true, answer }, 'server');
        out.sent += 1;
        out.events.push(e);
      } else if (res.status >= 500 && res.status !== 503) {
        continue;
      } else {
        let why = '';
        try { why = (await res.json()).error || ''; } catch { /* no reason given */ }
        dropWaiting(e);
        forget(e);
        failed(e, `not saved: ${res.status}${why ? ` (${why})` : ''}`, true);
        out.refused += 1;
      }
    }
  } finally {
    flushing = false;
  }
  return out;
}

// Every open crew screen looks at the station computer every ALARM_RULES.pollSeconds while someone is signed in:
// new crew lines and the ship's readings come in, the banner and Today are drawn again, and a new crewmate alarm
// sounds (FS-01, HF-01, PO-1). The same look sends what waits in this browser, and notices when a server that did
// not answer is back. The crew screen still reads only its person's events (/api/events?person=<id>).
let pollTimer = 0;
let polling = false;
function schedulePoll(seconds = ALARM_RULES.pollSeconds) {
  clearTimeout(pollTimer);
  pollTimer = 0;
  if (!ownServer()) return;
  if (!ui.person && !waiting.length) return;
  pollTimer = setTimeout(pollOnce, seconds * 1000);
}
async function pollOnce() {
  if (polling) return;
  polling = true;
  try {
    const person = ui.person;
    // The sign-in screen only sends what waits (a call for help from there, or the record of someone who signed out).
    if (!person) {
      const f = waiting.length ? await flushWaiting() : { reached: false };
      if (f.reached && serverDown) { serverDown = false; store = null; }
      checkHelpCall();
      return;
    }
    if (waiting.length && !serverDown) await flushWaiting();
    if (personById[person].real) return;
    const res = await fetch(apiUrl(`./api/events?person=${encodeURIComponent(person)}`), { headers: { Accept: 'application/json' }, cache: 'no-store' });
    if (!res.ok || !(res.headers.get('content-type') || '').includes('application/json')) return;
    const events = await res.json();
    if (ui.person !== person || !Array.isArray(events)) return;
    if (serverDown || !store || store.kind !== 'server') { await reconnect(person); return; }
    const fresh = newShared(events, stored, { ship: SHIP.id });
    // Steps of this person's alert log written on another screen: the same alerts read and acknowledged here too.
    const logged = newOwnLog(events, stored, person, eventKey);
    if (logged.length) { stored.push(...logged); applyLog(); }
    if (fresh.length) {
      stored.push(...fresh);
      if (fresh.some((e) => e.kind === 'reading')) rebuild();
    }
    if (fresh.length || logged.length) redrawShared();
    checkHelpCall();
  } catch {
    // no answer this time: the next look tries again
  } finally {
    polling = false;
    schedulePoll(waiting.length ? ALARM_RULES.retrySeconds : ALARM_RULES.pollSeconds);
  }
}
// The banner, the Messages key and Today again, without touching a form the person may be typing in.
function redrawShared() {
  renderBar();
  if (ui.screen === 'home') renderHome();
  else if (ui.screen === 'alerts') renderAlerts();
}
// The station server answers again: send what waited, then read the record from the server.
async function reconnect(person) {
  // serverDown stays true until the server's store is open, so what is entered meanwhile still waits in this browser.
  const sent = await flushWaiting();
  if (!sent.reached && waiting.length) return;
  let s;
  try { s = await openStore({ person }); } catch { return; }
  if (ui.person !== person || !s || s.kind !== 'server') return;
  const late = waiting.length ? await flushWaiting() : { events: [] };
  store = s;
  serverDown = false;
  stored = withWaiting([...s.events, ...sent.events, ...late.events], person);
  await readOutbox();
  applyLog(); // steps of the alert log written on the person's other screens meanwhile
  rebuild();
  render();
  checkHelpCall();
  toast(`The station server answers again.${sent.sent ? ` ${sent.sent} ${sent.sent === 1 ? 'record' : 'records'} kept in this browser ${sent.sent === 1 ? 'is' : 'are'} saved there now.` : ''}${sent.refused ? ` ${sent.refused} could not be saved: see Sent messages.` : ''}`);
}

// What a sent message became, in words; null when it was not saved (keep() has already said so).
function sentText(to, res, what = 'The message') {
  if (!res || !res.ok) return null;
  const st = messageStatus(res, { to, storeKind: store ? store.kind : 'memory' });
  if (st === 'waiting') return `${what} is kept in this browser: the station server is not answering, and it goes there${to === 'doctor-earth' ? ' and into the outbox' : ''} when it answers again.`;
  if (st === 'onboard') return `${what} is saved for the doctor on board.`;
  if (st === 'queued') return `${what} is sealed in the outbox: it goes ${ui.ship.linkToEarth ? 'with the next downlink' : 'when the link is back'}.`;
  if (st === 'local') return `${what} is saved on this computer only: this copy runs without the station server, so nothing is sent.`;
  return `${what} is saved on the station server.`;
}

// ---------- the crew alarm ----------
// A crewmate's screen learns only that this person needs help now, never the rest of the record
// (14 CFR 1214.403: crewmembers may not use another's medical information without consent). A new line is written
// whenever the set of urgent signs changes, and an all clear when it ends (FS-05); each urgent line also sends an
// automatic message to the doctor, so "a doctor has been called" is true (FS-02).
const HOUR_MS = 60 * 60 * 1000;
const HELP_SOURCE = { id: 'help-key', indicator: 'camera' };
const URGENT_LABELS = CELLS.filter((c) => c.section !== 'env' && (c.red || []).some((r) => r.level === 'urgent')).map((c) => c.label);
const SIGN_TOKENS = [...URGENT_LABELS, 'Help key', 'camera'];
const CAMERA_SIGN = { chest_grab: 'the camera saw a hand held to the chest', chest_grab_help: 'answered "I need help" to the camera question', chest_grab_no_answer: 'no answer to the camera question "Are you okay?"' };

// The newest camera or Help key alarm of the last day, unless a later "I am okay" cleared it (the rule
// state-levels.js follows too). Made-up example events never raise a crew alarm.
function cameraAlarm(personId, now = nowTime()) {
  const cam = machine.history(personId, 'camera').filter((x) => msOf(now) - msOf(x.time) <= LEVEL_RULES.cameraHours * HOUR_MS);
  let i = cam.length - 1;
  while (i >= 0 && cam[i].status !== STATUS.OUT) i -= 1;
  if (i < 0 || cam[i].example || cam.slice(i + 1).some((x) => x.value === 'chest_grab_ok')) return null;
  return cam[i];
}
// The urgent signs of one person now, from real readings only.
function urgentSigns(p) {
  const now = nowTime();
  const a = assess({ machine, person: p, cells: CELLS, mission: mission(), now });
  const reds = a.body.items.filter((x) => x.kind === 'red' && x.level >= LEVEL.URGENT && x.m && x.m.last && !x.m.last.example);
  const cam = cameraAlarm(p.id, now);
  const helpKey = Boolean(cam && cam.source === HELP_SOURCE.id);
  const tokens = [...(cam ? [helpKey ? 'Help key' : 'camera'] : []), ...reds.map((x) => x.cell.label)];
  const signs = [...(cam && !helpKey ? [CAMERA_SIGN[cam.value] || 'a camera alarm'] : []), ...reds.map((x) => `${x.cell.label} ${valueText(x.cell.indicator, x.m.last.value)} ${x.cell.unit || ''}`.trim())];
  const what = [
    ...(cam ? [helpKey ? `${p.name} pressed the Help key, GMT ${gmtDOY(cam.time)}.` : `The camera saw a hand held to the chest, and ${cam.value === 'chest_grab_help' ? `${p.name} answered "I need help"` : 'there was no answer to "Are you okay?"'}, GMT ${gmtDOY(cam.time)}.`] : []),
    ...reds.map((x) => `${x.cell.label} ${itemText(x, p).text}`),
  ];
  return { cam, helpKey, tokens, signs, what };
}
// The latest value of each sign a line named, for the all clear: "Blood oxygen (SpO2) 98 %".
function valuesNamedIn(p, text) {
  return CELLS.filter((c) => URGENT_LABELS.includes(c.label) && String(text).includes(c.label)).map((c) => {
    const last = machine.history(p.id, c.indicator).slice(-1)[0];
    return last ? `${c.label} ${valueText(c.indicator, last.value)} ${c.unit || ''}`.trim() : null;
  }).filter(Boolean);
}
const crewSentence = (st, clear) => ({
  shared: clear ? 'The crew screens on board stop showing the alarm.' : 'The crew screens on board show the alarm.',
  local: 'This copy runs without the station server: no other crew screen has it.',
  waiting: 'The crew line was still waiting for the station computer when this was written.',
  unsent: 'The crew line was not saved.',
})[st] || '';

async function shareCrewAlarm(personId, { force = false, falseAlarm = false, drillEnd = null } = {}) {
  const p = personById[personId];
  if (!p || p.real || personId === SHIP.id) return null;
  // While a drill runs, its readings count for the alarm (src/drill.js); a real urgent sign is never marked as a drill.
  // While a real urgent sign is present the line is the real one, made from the record's signs only, so a drill's
  // value never reaches the crew or the doctor inside a real alarm (the drill's alarm still sounds on this screen).
  const real = drillMachine ? urgentSigns(p) : null;
  const u = drillMachine && !real.tokens.length ? withMachine(drillMachine, () => urgentSigns(p)) : real || urgentSigns(p);
  const last = latestLine(stored, personId);
  if (!force && !needsNewLine(last, u.tokens, SIGN_TOKENS)) return null;
  const time = new Date().toISOString();
  const clear = !u.tokens.length;
  const drill = lineDrill({ drill: drillMachine ? ui.drill : null, ended: drillEnd, realSigns: real ? real.tokens.length : 0, clear, lastWasDrill: Boolean(last && isDrill(last)) });
  // The all clear that ends a drill's line says so: the record's own values say nothing about the drill's.
  const drillDone = Boolean(drillEnd && drill && clear);
  const named = last && !last.alarm.clear && !drillDone ? valuesNamedIn(p, last.alarm.text) : [];
  const plain = clear ? (falseAlarm ? falseAlarmText(p.name) : allClearText(p.name, drillDone ? 'the drill is over' : named.join('; '))) : alarmText(p.name, { helpKey: u.helpKey, signs: u.signs });
  const text = drill ? drillLine(plain) : plain;
  const line = { v: 1, kind: 'alarm', time, person: personId, ...(drill ? { drill } : {}), alarm: clear ? { text, clear: true } : { text } };
  const lineRes = await keep(line, { quiet: true, retry: true, mark: false });
  const gone = falseAlarm ? [`${p.name} pressed "I am okay: false alarm" at GMT ${gmtDOY(time)}.`] : [];
  const what = clear ? [...gone, falseAlarm ? '' : drillDone ? 'The drill is over.' : `No reading is past an urgent limit now${named.length ? `: ${named.join('; ')}` : ''}.`, last && !last.alarm.clear ? `The crew line of GMT ${gmtDOY(last.time)} is over.` : ''] : [...gone, ...u.what];
  const body = alarmReportText({ name: p.name, gmt: gmtDOY(time), what, clear, crew: crewSentence(statusOf(line), clear) });
  const report = {
    v: 1, kind: 'report', time, person: personId, state: { ...ui.ship }, ...(drill ? { drill } : {}),
    report: { to: ui.ship.doctorOnBoard ? 'doctor-onboard' : 'doctor-earth', text: drill ? drillReport(body) : body, topic: clear ? 'alarm-clear' : 'alarm' },
  };
  const reportRes = await keep(report, { quiet: true, retry: true, mark: false });
  return { line, lineRes, report, reportRes, clear };
}

// Every new reading goes through the machine and is saved, exactly like on the technical page. A reading that was
// not saved leaves the screen again. share: false skips the crew alarm (the false alarm writes its own line).
// real: a reading that answers a real alarm during a drill ("I am okay: false alarm" on it) is the record's, never the
// drill's, so the real alarm is called off in the record and does not ring again when the drill ends.
async function addReading(indicator, value, { source = null, person = ui.person, context = null, time = null, detail = null, quiet = false, retry = false, share = true, force = false, real = false } = {}) {
  const src = source || sourceFor(indicator);
  const event = { v: 1, kind: 'reading', time: time || new Date().toISOString(), person, state: { ...ui.ship }, reading: { source: src.id, indicator, value, ...(context ? { context } : {}), ...(detail ? { detail } : {}) } };
  // A drill's reading goes into the drill's machine only, never into the record's (src/drill.js).
  const drill = real ? null : markFor(ui.drill, event.time);
  if (drill && drillMachine) event.drill = drill;
  const m = event.drill ? drillMachine : machine;
  m.setState(event.state);
  const entry = m.receive({ ...event.reading, person, time: event.time });
  // The drill's machine holds the record too, so a reading of the record reaches both.
  if (!event.drill && drillMachine) { drillMachine.setState(event.state); drillMachine.receive({ ...event.reading, person, time: event.time }); }
  const res = await keep(event, { quiet, retry, mark: !real });
  // Not saved: the machine forgets it again; the screen was not redrawn with it, so a form keeps what was typed.
  if (!res.ok) { rebuild(); renderBar(); return { entry, ok: false, why: res.why }; }
  const shared = share ? await shareCrewAlarm(person, { force }) : null;
  render();
  return { entry, ok: true, waiting: Boolean(res.waiting), shared };
}
// "Saved", or what happened instead, for the toasts of the forms.
const savedWord = (res, ok = 'Saved') => (res && res.waiting ? 'Kept in this browser until the station server answers' : ok);

// ---------- the person's measures ----------
// The tiles follow the machine's cells, so a new measure in config.js shows up here by itself.
const tileCells = (section) => CELLS.filter((c) => c.section === section && (c.kind === KIND.NUMBER || c.kind === KIND.SELF) && !c.private).map((c) => c.indicator);
const COMPLEX_CELLS = CELLS.filter((c) => c.kind === KIND.COMPLEX).map((c) => c.indicator);
const BODY = tileCells('body');
const PSYCHE = tileCells('psyche');
const SHIP_CELLS = tileCells('env');
const ORDINAL = {
  mood: { 1: 'bad', 2: 'fair', 3: 'good' },
  // Energy: the steps of the Samn-Perelli fatigue scale, 1 fully alert to 7 completely exhausted (src/fatigue.js).
  attitude: Object.fromEntries(FATIGUE_STEPS.map((s) => [s.step, String(s.step)])),
};
const LOW_TEXT = { mood: 'Bad', attitude: `Tired: ${FATIGUE_RULE.lowFrom} or more (a draft)` };
const isLowAnswer = (ind, v) => (ind === 'attitude' ? isLowEnergy(v) : v === 'bad');
const ordinalValue = (ind, v) => {
  if (ind === 'attitude') return fatigueStep(v);
  const hit = Object.entries(ORDINAL[ind]).find(([, n]) => n === v);
  return hit ? Number(hit[0]) : NaN;
};

function seriesOf(ownerId, indicator) {
  const cell = cellBy[indicator];
  const list = machine.history(ownerId, indicator);
  if (indicator === 'bp') {
    return [
      { name: 'systolic', color: 'var(--series-1)', points: list.map((x) => ({ t: msOf(x.time), v: Number(x.value.sys), out: !(Number(x.value.sys) < cell.norm.sysBelow) })) },
      { name: 'diastolic', color: 'var(--series-2)', points: list.map((x) => ({ t: msOf(x.time), v: Number(x.value.dia), out: !(Number(x.value.dia) < cell.norm.diaBelow) })) },
    ];
  }
  if (ORDINAL[indicator]) {
    const name = indicator === 'attitude' ? 'energy (1 fully alert, 7 completely exhausted)' : lower(cell.label);
    return [{ name, color: 'var(--series-1)', points: list.map((x) => ({ t: msOf(x.time), v: ordinalValue(indicator, x.value), out: isLowAnswer(indicator, x.value) })).filter((p) => Number.isFinite(p.v)) }];
  }
  return [{ name: lower(cell.label), color: 'var(--series-1)', points: list.map((x) => ({ t: msOf(x.time), v: Number(x.value), out: x.status === STATUS.OUT })).filter((p) => Number.isFinite(p.v)) }];
}

function bandOf(cell, owner) {
  if (cell.normType === 'range') return { min: cell.norm.min, max: cell.norm.max };
  if (cell.normType === 'baseline-shift') return hearingBand(machine.history(owner.id, cell.indicator), cell);
  if (cell.normType === 'baseline-percent') {
    const base = owner && owner.baselines ? Number(owner.baselines[cell.baselineKey]) : NaN;
    return Number.isFinite(base) ? { min: (base * cell.norm.minPercent) / 100, max: null } : null;
  }
  return null;
}

// The normal range in words, without the word itself: "36.1 to 37.2", "below 120/80", "7 or more".
function rangeText(cell, owner) {
  if (cell.normType === 'range') {
    const n = cell.norm;
    if (n.minBySex) {
      const v = n.minBySex[owner && owner.sex] ?? Math.min(...Object.values(n.minBySex));
      return `${v} or more`;
    }
    if (n.min !== null && n.max !== null) return `${n.min} to ${n.max}`;
    if (n.min !== null) return `${n.min} or more`;
    return `${n.maxExclusive ? 'below' : 'up to'} ${n.max}`;
  }
  if (cell.normType === 'below-both') return `below ${cell.norm.sysBelow}/${cell.norm.diaBelow}`;
  if (cell.normType === 'baseline-shift') return hearingRangeText(machine.history(owner.id, cell.indicator), cell);
  return normShort(cell, owner);
}
// The range with its unit on a measure's page: "95% or more of own pre-flight", not "95 or more % of own pre-flight"
// (body mass). A range said in words of its own (own pre-flight level, hearing) takes no unit.
function rangeWithUnit(cell, owner) {
  const r = rangeText(cell, owner);
  if (!cell.unit || cell.kind !== KIND.NUMBER || cell.normType === 'baseline-percent' || cell.normType === 'baseline-shift') return r;
  return cell.unit.startsWith('% ') && r.endsWith(' or more') ? `${r.slice(0, -' or more'.length)}% or more ${cell.unit.slice(2)}` : `${r} ${cell.unit}`;
}

function normShort(cell, owner) {
  if (cell.normType === 'range' || cell.normType === 'below-both' || cell.normType === 'baseline-shift') return `normal range ${rangeText(cell, owner)}`;
  if (cell.normType === 'baseline-percent') {
    const b = bandOf(cell, owner);
    return b ? `at least ${fmtVal(b.min)} (${cell.norm.minPercent}% of own level)` : 'no pre-flight level';
  }
  return '';
}

const CAMERA_TEXT = { sleeping: 'asleep', chest_grab: 'hand on chest', chest_grab_ok: 'answered "okay"', chest_grab_help: 'answered "need help"', chest_grab_no_answer: 'no answer' };
function valueText(indicator, value) {
  if (value === null || value === undefined) return '';
  const logged = logText(indicator, value);
  if (logged !== null && logged !== undefined) return logged;
  if (indicator === 'cognition' && Number.isFinite(Number(value)) && typeof value !== 'string') return `${Math.round(Number(value))} ms`;
  if (indicator === 'bp' && typeof value === 'object') return `${value.sys}/${value.dia}`;
  if (indicator === 'camera') return CAMERA_TEXT[value] || String(value);
  if (indicator === 'attitude') return fatigueWords(value);
  if (indicator === 'bone' && typeof value === 'object') return `${value.hipSpine}% and ${value.neck}%`;
  return fmtVal(value);
}

// The words of a red limit: "at or below 88", "above 180".
const limitWords = (red) => `${({ atOrBelow: 'at or below', atOrAbove: 'at or above', below: 'below', above: 'above' })[red.when] || red.when} ${red.value}`;

// The crew line and the automatic message to the doctor of one person's current alarm (those written from since on),
// so the screen says what really happened to them instead of what should have (FS-02, FS-04).
const SINCE_SLACK_MS = 60 * 1000;
function alarmLineOf(personId, since = 0) {
  const lines = stored.filter((e) => e.kind === 'alarm' && e.person === personId && e.alarm && !e.alarm.clear && msOf(e.time) >= since - SINCE_SLACK_MS);
  return lines.sort((a, b) => msOf(a.time) - msOf(b.time)).slice(-1)[0] || null;
}
function alarmReportOf(personId, since = 0) {
  const mine = [...stored, ...unsent.map((u) => u.event)].filter((e) => e.kind === 'report' && e.person === personId && e.report && e.report.topic === 'alarm' && msOf(e.time) >= since - SINCE_SLACK_MS);
  return mine.sort((a, b) => msOf(a.time) - msOf(b.time)).slice(-1)[0] || null;
}
const isHelpKeyItem = (it, ownerId) => { const c = it.kind === 'camera' ? machine.history(ownerId, 'camera').filter((x) => x.status === STATUS.OUT).slice(-1)[0] : null; return Boolean(c && c.source === HELP_SOURCE.id); };

// What one item of the assessment says, in plain words.
// A strong headache also says the cabin CO2 before it (src/nasa-rules.js, Law et al., 2014).
function headacheAir(it, owner) {
  const link = co2Link();
  const x = it.rule === 'strong-symptom' && link ? (it.entries || []).find((e) => e.value && e.value.symptom === link.symptom) : null;
  return x ? ` Headache of GMT ${gmtDOY(x.time)}: ${co2Short(co2Around(machine.history(SHIP.id, 'co2'), x.time, { link }))}.` : '';
}
function itemText(it, owner) {
  if (it.kind === 'tell') return { title: it.title, text: `${it.text}${headacheAir(it, owner)}`, time: it.time }; // the levels word these items themselves (state-levels.js)
  if (it.kind === 'camera') {
    const doc = doctorWords(statusOf(alarmReportOf(owner.id, msOf(it.time))), ui.ship);
    if (isHelpKeyItem(it, owner.id)) return { title: 'Help requested with the Help key', text: `You held the Help key. ${doc}`, time: it.time };
    return { title: 'Camera: alarm after the question "Are you okay?"', text: `${it.value === 'chest_grab_help' ? 'You answered that you need help' : 'There was no answer'}. ${doc}`, time: it.time };
  }
  if (it.kind === 'mood') return { title: 'Mood and energy', text: `Low check-ins in the last ${LEVEL_RULES.psycheDays} days: ${it.days} ${it.days === 1 ? 'day' : 'days'}. The planned review will look at this.`, time: null };
  const cell = it.cell;
  const last = it.m.last;
  const v = `${valueText(cell.indicator, last.value)} ${cell.unit || ''}`.trim();
  if (it.kind === 'forecast') {
    const c = it.m.forecast.crossing;
    return { title: cell.label, text: `The last reading, ${v}, is still within the normal range, but the line through the readings leaves it ${c.side === 'below' ? 'downwards' : 'upwards'} around ${fmtDate(c.date)}, before landing on ${fmtDate(mission().landing)}.`, time: last.time };
  }
  const side = it.m.side === 'below' ? 'below' : 'above';
  if (it.kind === 'red') return { title: owner && owner.id === SHIP.id ? `${it.level >= LEVEL.URGENT ? 'Ship emergency' : 'Ship caution'}: ${lower(cell.label)}` : cell.label, text: `${v}: ${limitWords(it.red)}${it.red.part ? ` (${it.red.part})` : ''}, the ${it.level >= LEVEL.URGENT ? 'urgent' : 'needs-action'} limit (${it.red.source}).`, time: last.time };
  if (it.kind === 'standard') return { title: cell.label, text: `${v}: ${side} the NASA standard (${normShort(cell, owner)}).`, time: last.time };
  if (it.kind === 'expected') return { title: cell.label, text: `${v}: ${side} the usual range on Earth (${rangeText(cell, owner)}). ${it.expected.text}`, time: last.time };
  const others = (it.together || []).filter((x) => x !== cell.indicator && cellBy[x]).map((x) => lower(cellBy[x].label));
  return { title: cell.label, text: `${v}: ${side} the normal range (${rangeText(cell, owner)})${it.m.streak > 1 ? `, ${it.m.streak} readings in a row` : ''}. Reading of ${fmtDT(last.time)}.${others.length ? ` Out of range at the same time: ${others.join(' and ')}. Several vital signs out together count more than one (NEWS2).` : ''}`, time: last.time };
}

// Low blood sugar is treated first, then measured again: ADA's 15-15 rule ("In most conscious individuals, have 15
// grams of fast-acting carbohydrates, and recheck glucose in 15 minutes"; ADA hypoglycemia sheet, 2025, and the ADA
// page below, both read on 15 Nov 2026). The other signs keep their steps (FS-07).
const SUGAR_STEP = {
  text: 'You, if you are awake and can swallow: take 15 g of fast sugar now (glucose tablets or gel, or half a cup of juice or regular soda), then check again in 15 minutes; if it is still below 70, take 15 g more.',
  link: { name: 'ADA: the 15-15 rule', url: 'https://diabetes.org/living-with-diabetes/hypoglycemia-low-blood-glucose/symptoms-treatment' },
};

// What to do, by the program's rules (shown in magenta, like NASA's electronic procedures). The automation steps say
// what really happened to the crew line and the message to the doctor.
function procedureFor(it, personId = ui.person) {
  const reachable = ui.ship.doctorOnBoard || ui.ship.linkToEarth;
  if (it.kind === 'red' && it.cell && it.cell.section === 'env') return ['Follow the ship\'s own procedure for this alarm; this screen only mirrors the ship.', 'The crew and mission control decide.'];
  const sugar = it.kind === 'red' && it.cell && it.cell.indicator === 'glucose' && it.m && it.m.side === 'below' ? [SUGAR_STEP] : [];
  const since = alarmSince(it);
  const crewStep = () => crewWords(statusOf(alarmLineOf(personId, since)));
  const doctorStep = () => doctorWords(statusOf(alarmReportOf(personId, since)), ui.ship);
  if (it.kind === 'red' && it.level >= LEVEL.URGENT) return [...sugar, crewStep(), ...(sugar.length ? [] : ['You: repeat the reading now if you can, at rest.']), doctorStep(), 'Crew medical officer: open the emergency procedure for this sign.'];
  if (it.kind === 'red') return [...sugar, ...(sugar.length ? [] : ['You: repeat the reading now, at rest if you can.']), 'You: if it stays past the limit, tell the crew medical officer.', reachable ? 'You: message the doctor with the "Message the doctor" button.' : 'You: message the doctor with the "Message the doctor" button; with no link it waits in the outbox and goes when the link is back.'];
  switch (it.kind) {
    case 'camera': return [crewStep(), doctorStep(), 'If the alarm was a mistake, press "I am okay: false alarm": the crew screens clear and the doctor gets a note.', 'The question "Are you okay?" and its waiting time can be changed in the rules.'];
    case 'standard': return ['Repeat the test in the next few days.', 'Show the result to the doctor: the "Message the doctor" button.', 'NASA standard: at least 80% of your own pre-flight level.'];
    case 'forecast': return ['Take a new reading.', 'If the line is confirmed, tell the doctor.', 'The forecast here is a straight line through the readings, not a medical model.'];
    case 'expected': return ['This is a common change in flight; the source is named in the explanation.', 'If you feel unwell, tell the doctor.'];
    case 'mood': return ['The planned review will look at the check-ins.', 'You can start an anonymous session with the AI or write to the doctor on Earth.'];
    case 'tell': return it.steps;
    default: return ['Repeat the reading.', 'If it is outside the normal range again, press "Analyse with AI" or "Message the doctor".'];
  }
}

// ---------- mission profile ----------
// Where the crew is decides how far help is. Delays are one way; sources: NASA HRP-48021 (Mars, up to about
// 22 minutes one way, with two-week blackouts near solar conjunction) and the Earth-Moon distance (about 1.3 s).
const PROFILES = {
  iss: { name: 'ISS, low Earth orbit', delay: 'under a second', reply: 'a reply can come within minutes', evac: 'a return to Earth is possible within hours' },
  moon: { name: 'Moon (orbit or surface)', delay: 'about 1.3 seconds', reply: 'a reply can come within minutes', evac: 'a return to Earth takes days' },
  mars: { name: 'Mars transit or surface', delay: 'up to about 22 minutes', reply: 'a reply takes at least twice the delay, up to about 44 minutes, and the link can be down for two weeks near solar conjunction', evac: 'no return to Earth for many months' },
};
const profile = () => PROFILES[ui.profile] || PROFILES.iss;

// ---------- "?" explanations ----------
const SELF_SOURCES = ['mood-report', 'attitude-report', 'sleep-rating', 'cycle-log', 'cognition-test', 'reaction-test', ...SOURCES.filter((s) => s.self).map((s) => s.id)];
function thisValue(owner, last) {
  if (!last) return 'No reading yet.';
  const r = last;
  const when = stamp(last.time, nowTime());
  if (owner && owner.real) return `A real lab result from NASA OSDR (Inspiration4), ${when}.`;
  if (r.source === 'ble-heart-rate') return `Live from your Bluetooth heart rate monitor, ${when}.`;
  if (r.source === 'manual') return `Typed in by hand, ${when}.`;
  if (r.example) return `Made-up example data, shaped like published flight studies (${when}).`;
  if (SELF_SOURCES.includes(r.source)) return `Your own answer, ${when}.`;
  if (r.source === 'camera') return `This computer's camera model, ${when}.`;
  const info = sourceInfo(r.source);
  if (info.thisValue && info.origin !== 'simulated' && info.origin !== 'unknown') return `${info.thisValue}, ${when}.`;
  const src = SOURCES.find((s) => s.id === r.source);
  return `Entered on the technical view from a simulated "${src ? src.label : r.source}", ${when}.`;
}
const linkList = (list) => list.flatMap((d, i) => [i ? '; ' : '', d.url ? h('a', { href: d.url, target: '_blank', rel: 'noopener' }, d.name) : d.name, d.maker ? ` (${d.maker})` : '']);
